mapper.select:
SELECT EXISTS (
SELECT 1
FROM suspects
WHERE case_id = #{caseId}
AND id = #{suspectId}
)

SELECT EXISTS (
SELECT 1
FROM evidences
WHERE case_id = #{caseId}
AND id = #{evidenceId}
)

SELECT EXISTS (
SELECT 1
FROM case_solutions cs
INNER JOIN case_solution_evidences cse
ON cse.case_solution_id = cs.id
WHERE cs.case_id = #{caseId}
AND cse.evidence_id = #{evidenceId}
)
